typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K, Tds> Dt;
typedef Dt::Point Cp;
typedef Dt::Face_handle Face_handle;
typedef Dt::Finite_faces_iterator Finite_faces_iterator;

Dt dt;
for (const auto& p : points) {
    dt.insert(Cp(p.x(), p.y()));
}

std::vector<bool> keep_face(dt.number_of_faces(), false);
int face_index = 0;
for (Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit, ++face_index) {
    Cp circumcenter = dt.dual(fit);
    double circumradius = sqrt(dt.segment(fit, 0).squared_length() + dt.segment(fit, 1).squared_length() + dt.segment(fit, 2).squared_length()) / 2.0;
    if (circumradius <= alpha) {
        keep_face[face_index] = true;
    }
}

// Count connected components using DFS
std::vector<bool> visited(dt.number_of_faces(), false);
int components = 0;
for (Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    int idx = std::distance(dt.finite_faces_begin(), fit);
    if (keep_face[idx] && !visited[idx]) {
        components++;
        std::vector<Face_handle> stack;
        stack.push_back(fit);
        visited[idx] = true;
        while (!stack.empty()) {
            Face_handle current = stack.back();
            stack.pop_back();
            int current_idx = std::distance(dt.finite_faces_begin(), current);
            for (int i = 0; i < 3; ++i) {
                Face_handle neighbor = current->neighbor(i);
                if (dt.is_infinite(neighbor)) continue;
                int neighbor_idx = std::distance(dt.finite_faces_begin(), neighbor);
                if (keep_face[neighbor_idx] && !visited[neighbor_idx]) {
                    visited[neighbor_idx] = true;
                    stack.push_back(neighbor);
                }
            }
        }
    }
}
return components;

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K, Tds> Dt;
typedef Dt::Point Cp;
typedef Dt::Face_handle Face_handle;
typedef Dt::Finite_faces_iterator Finite_faces_iterator;

Dt dt;
for (const auto& p : points) {
    dt.insert(Cp(p.x(), p.y()));
}

std::vector<bool> keep_face;
keep_face.reserve(dt.number_of_faces());

for (Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    Cp p1 = fit->vertex(0)->point();
    Cp p2 = fit->vertex(1)->point();
    Cp p3 = fit->vertex(2)->point();

