typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K, Tds> Dt;
typedef Dt::Point Cp;
typedef Dt::Face_handle Face_handle;

Dt dt;
for (const auto& p : points) {
    dt.insert(Cp(p.x(), p.y()));
}

std::vector<bool> keep_face;
keep_face.reserve(dt.number_of_faces());

for (auto fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    Cp p1 = fit->vertex(0)->point();
    Cp p2 = fit->vertex(1)->point();
    Cp p3 = fit->vertex(2)->point();

    double a = sqrt((p1.x() - p2.x()) * (p1.x() - p2.x()) + (p1.y() - p2.y()) * (p1.y() - p2.y()));
    double b = sqrt((p2.x() - p3.x()) * (p2.x() - p3.x()) + (p2.y() - p3.y()) * (p2.y() - p3.y()));
    double c = sqrt((p3.x() - p1.x()) * (p3.x() - p1.x()) + (p3.y() - p1.y()) * (p3.y() - p1.y()));

    if (a <= 1e-10 || b <= 1e-10 || c <= 1e-10) {
        keep_face.push_back(false);
        continue;
    }

    double s = (a + b + c) / 2.0;
    double area_sq = s * (s - a) * (s - b) * (s - c);
    if (area_sq <= 0) {
        keep_face.push_back(false);
        continue;
    }

    double area = sqrt(area_sq);
    double circumradius = (a * b * c) / (4.0 * area);
    keep_face.push_back(circumradius <= alpha);
}

std::vector<bool> visited(dt.number_of_faces(), false);
int components = 0;
int face_index = 0;

for (auto fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit, ++face_index) {
    if (keep_face[face_index] && !visited[face_index]) {
        components++;
        std::vector<Face_handle> stack;
        stack.push_back(fit);
        visited[face_index] = true;

        while (!stack.empty()) {
            Face_handle current = stack.back();
            stack.pop_back();

            for (int i = 0; i < 3; ++i) {
                Face_handle neighbor = current->neighbor(i);
                if (dt.is_infinite(neighbor)) continue;

                int neighbor_idx = 0;
                auto neighbor_it = dt.finite_faces_begin();
                while (neighbor_it != dt.finite_faces_end()) {
                    if (neighbor_it == neighbor) break;
                    ++neighbor_it;
                    ++neighbor_idx;
                }

                if (neighbor_it != dt.finite_faces_end() && keep_face[neighbor_idx] && !visited[neighbor_idx]) {
                    visited[neighbor_idx] = true;
                    stack.push_back(neighbor);
                }
            }
        }
    }
}

return components;
